document.addEventListener("click",e=>{
  const o=e.target.closest&&e.target.closest(".rq-opt,.rq-reset");if(!o)return;
  const m=o.dataset.m,st=ALGO_STATE[m];if(!st)return;
  if(o.classList.contains("rq-reset")){for(const k in st)delete st[k];const box=document.getElementById("rq-"+m);if(box){box.outerHTML=algoQuiz(m);if(typeof pathLinks==="function")pathLinks(document.getElementById("rq-"+m))}return}
  st[o.dataset.q]=o.dataset.v;
  o.closest(".rq-opts").querySelectorAll(".rq-opt").forEach(b=>b.setAttribute("aria-pressed",String(b===o)));
  const r=document.getElementById("rq-res-"+m);if(r){r.innerHTML=algoResult(m);if(typeof pathLinks==="function")pathLinks(r)}
});
/* v2 (21/11/2026): « Comment ça marche » — mécanismes + Vrai ou faux */
Object.assign(ALGO,{
 meca_h:A3("How it works: the mechanisms","Comment ça marche : les mécanismes","Cómo funciona: los mecanismos"),
 meca_p:A3("Seven mechanisms to read any outlet or influencer. Open each card: it ends with the question to ask.","Sept mécanismes pour lire n’importe quel média ou influenceur. Dépliez chaque carte : elle se termine par la question à se poser.","Siete mecanismos para leer cualquier medio o influencer. Despliega cada tarjeta: termina con la pregunta que hacerse."),
 ask:A3("The question to ask","La question à se poser","La pregunta que hacerse"),
 meca:[
  [A3("Public media: who pays, and what for","Le média public : qui le paie, à quoi il sert","El medio público: quién lo paga y para qué"),
   A3("It is funded by everyone’s money: a tax or a licence fee depending on the country. In France, the licence fee was abolished in 2022 and replaced by a share of VAT, a system made permanent in December 2024. In return, it must offer impartial information and a plurality of views, for every audience. Criticising it is normal and healthy: it is our money.","Il est financé par l’argent de tous : impôt ou redevance selon les pays. En France, la redevance a été supprimée en 2022 et remplacée par une part de la TVA, un mode de financement rendu durable en décembre 2024. En échange, il doit offrir une information impartiale et des points de vue pluralistes, pour tous les publics. Le critiquer est normal et sain : c’est notre argent.","Se financia con el dinero de todos: impuesto o canon según el país. En Francia, el canon se suprimió en 2022 y se sustituyó por una parte del IVA, un sistema consolidado en diciembre de 2024. A cambio, debe ofrecer información imparcial y pluralidad de opiniones, para todos los públicos. Criticarlo es normal y sano: es nuestro dinero."),
   A3("Does it meet its pluralism obligations? And those who want to cut or abolish it: what do they propose instead?","Respecte-t-il ses obligations de pluralisme ? Et ceux qui veulent le réduire ou le supprimer, que proposent-ils à la place ?","¿Cumple sus obligaciones de pluralismo? Y quienes quieren recortarlo o suprimirlo, ¿qué proponen a cambio?"),
   "https://www.vie-publique.fr/loi/295883-reforme-financement-de-laudiovisuel-public-loi-organique"],
  [A3("When one outlet criticises another","Quand un média en critique un autre","Cuando un medio critica a otro"),
   A3("Criticism between media is part of the debate. But an outlet attacking a rival is never a neutral referee: they compete for the same audience and often the same advertisers. When a private group denounces the public broadcaster, or the other way round, ask who would gain. The warning sign is a repeated campaign that serves the owner’s business or political interests.","La critique entre médias fait partie du débat. Mais un média qui attaque un concurrent n’est jamais un arbitre neutre : il se dispute le même public et souvent les mêmes annonceurs. Quand un groupe privé dénonce le service public, ou l’inverse, demandez-vous qui y gagnerait. Le signal d’alerte, c’est une campagne répétée qui sert les intérêts économiques ou politiques du propriétaire.","La crítica entre medios forma parte del debate. Pero un medio que ataca a un competidor nunca es un árbitro neutral: se disputan el mismo público y a menudo los mismos anunciantes. Cuando un grupo privado denuncia al servicio público, o al revés, pregúntate quién saldría ganando. La señal de alerta es una campaña repetida que sirve los intereses económicos o políticos del propietario."),
   A3("Does the critic have a stake: audience, advertising, its owner’s political project?","Celui qui critique a-t-il un intérêt : audience, publicité, projet politique de son propriétaire ?","¿Tiene interés quien critica: audiencia, publicidad, proyecto político de su propietario?")],
  [A3("Independent, opinion, partisan: three different things","Indépendant, d’opinion, partisan : trois choses différentes","Independiente, de opinión, partidista: tres cosas distintas"),
   A3("Independent: no shareholder or government can impose its editorial choices (ethics charter, journalists’ association, diversified funding). Opinion: it openly holds a line, left, right or elsewhere; that is an old democratic tradition, as long as it is stated. Partisan: it serves a party or a cause, sometimes while presenting itself as neutral news. Having a line is never the problem: hiding it is.","Indépendant : aucun actionnaire ni gouvernement ne peut imposer ses choix éditoriaux (charte, société de journalistes, financement diversifié). D’opinion : il assume une ligne, de gauche, de droite ou d’ailleurs ; c’est une vieille tradition démocratique, tant qu’elle est affichée. Partisan : il sert un parti ou une cause, parfois en se présentant comme de l’information neutre. Le problème n’est jamais d’avoir une ligne : c’est de la cacher.","Independiente: ningún accionista ni gobierno puede imponer sus decisiones editoriales (código ético, sociedad de redactores, financiación diversificada). De opinión: asume una línea, de izquierda, de derecha o de otro lugar; es una vieja tradición democrática, siempre que se declare. Partidista: sirve a un partido o una causa, a veces presentándose como información neutral. El problema nunca es tener una línea: es ocultarla."),
   A3("Does this outlet say clearly where it stands?","Ce média dit-il clairement d’où il parle ?","¿Dice este medio claramente desde dónde habla?")],
  [A3("The owner and the group","Le propriétaire et son groupe","El propietario y su grupo"),
   A3("Media are expensive and often earn little. When one person or group buys several, it is not always for the money: it is also influence. A group whose titles keep varied lines is not a problem. The warning sign is when all the outlets of the same owner push in the same political direction, whichever it is. In the EU, media must now disclose who owns them, and major concentrations are assessed for their impact on pluralism.","Un média coûte cher et rapporte souvent peu. Quand une personne ou un groupe en achète plusieurs, ce n’est pas toujours pour l’argent : c’est aussi de l’influence. Un groupe dont les titres gardent des lignes variées n’est pas un problème. Le signal d’alerte, c’est quand tous les médias d’un même propriétaire vont dans la même direction politique, quelle qu’elle soit. Dans l’UE, les médias doivent désormais publier qui les possède, et les grandes concentrations sont évaluées au regard du pluralisme.","Un medio cuesta caro y a menudo rinde poco. Cuando una persona o un grupo compra varios, no siempre es por dinero: también es influencia. Un grupo cuyos títulos mantienen líneas variadas no es un problema. La señal de alerta es cuando todos los medios de un mismo propietario van en la misma dirección política, sea cual sea. En la UE, los medios deben publicar ahora quién es su dueño, y las grandes concentraciones se evalúan según su impacto en el pluralismo."),
   A3("Do the owner’s other outlets all say the same thing?","Les autres médias du même propriétaire disent-ils tous la même chose ?","¿Dicen lo mismo todos los demás medios del mismo propietario?"),
   "https://media-board.europa.eu/news-0/new-era-media-regulation-europe-european-media-freedom-acts-main-obligations-become-applicable-2025-08-08_da"],
  [A3("How influencers make a living","Comment gagnent leur vie les influenceurs","Cómo se ganan la vida los influencers"),
   A3("Five main sources: a share of the platform’s advertising (on YouTube, 55% for long videos and 45% for Shorts), brand partnerships, affiliate links, subscriptions, donations and live gifts, and selling their own products. Their income depends on your attention: the more a video provokes a reaction, the more it pays. And sometimes a political message is paid for without being declared, as in Romania.","Cinq sources principales : une part de la publicité de la plateforme (sur YouTube, 55 % pour les vidéos longues et 45 % pour les Shorts), les partenariats avec des marques, les liens d’affiliation, les abonnements, dons et cadeaux en direct, et la vente de leurs propres produits. Leur revenu dépend de votre attention : plus une vidéo fait réagir, plus elle rapporte. Et parfois, un message politique est payé sans être déclaré, comme en Roumanie.","Cinco fuentes principales: una parte de la publicidad de la plataforma (en YouTube, el 55 % en vídeos largos y el 45 % en Shorts), colaboraciones con marcas, enlaces de afiliación, suscripciones, donaciones y regalos en directo, y la venta de sus propios productos. Sus ingresos dependen de tu atención: cuanto más reacciones provoca un vídeo, más rinde. Y a veces un mensaje político se paga sin declararlo, como en Rumanía."),
   A3("If this content makes me angry, who profits?","Si ce contenu me met en colère, qui en profite ?","Si este contenido me enfada, ¿quién se beneficia?"),
   "https://blog.youtube/news-and-events/new-opportunities-to-earn-and-changes-to-the-youtube-partner-program/"],
  [A3("Groups, channels and chats on social media","Groupes, chaînes et boucles sur les réseaux","Grupos, canales y chats en redes"),
   A3("A Facebook group, a Telegram channel or a WhatsApp chat can look like “ordinary citizens” and be run by activists or a party. That is not forbidden, but it should be clear. In Romania, the campaign also relied on volunteers coordinated through social media, alongside inauthentic accounts.","Un groupe Facebook, une chaîne Telegram ou une boucle WhatsApp peuvent avoir l’air « citoyens » et être animés par des militants ou par un parti. Ce n’est pas interdit, mais ce doit être clair. En Roumanie, la campagne s’appuyait aussi sur des bénévoles coordonnés via les réseaux, en plus de comptes inauthentiques.","Un grupo de Facebook, un canal de Telegram o un chat de WhatsApp pueden parecer «ciudadanos» y estar animados por militantes o por un partido. No está prohibido, pero debe ser claro. En Rumanía, la campaña se apoyó también en voluntarios coordinados por redes, además de cuentas inauténticas."),
   A3("Who runs this group, and do they say so?","Qui administre ce groupe, et le dit-il ?","¿Quién administra este grupo, y lo dice?"),
   "https://vsquare.org/?p=7420"],
  [A3("Who is invited, and at what time","Qui est invité, et à quelle heure","Quién es invitado, y a qué hora"),
   A3("In France, TV and radio channels report every month to the regulator, Arcom, which politicians they hosted and for how long; Arcom publishes a review every quarter. Since 2024, pluralism is also assessed through columnists, hosts and guests. Timing matters: a channel was formally warned for airing some parties’ speaking time at night while they were under-represented in the daytime. Many countries have a broadcasting regulator: look up what it publishes.","En France, les chaînes de télé et de radio communiquent chaque mois au régulateur, l’Arcom, la liste des personnalités politiques reçues et leur temps de parole ; l’Arcom en fait un bilan chaque trimestre. Depuis 2024, le pluralisme s’apprécie aussi avec les chroniqueurs, animateurs et invités. L’heure compte : une chaîne a déjà été mise en demeure pour avoir diffusé la nuit le temps de parole de certains partis, sous-représentés en journée. Beaucoup de pays ont un régulateur de l’audiovisuel : cherchez ce qu’il publie.","En Francia, las cadenas de tele y radio comunican cada mes al regulador, Arcom, qué políticos recibieron y durante cuánto tiempo; Arcom publica un balance cada trimestre. Desde 2024, el pluralismo se evalúa también con columnistas, presentadores e invitados. La hora cuenta: una cadena fue apercibida por emitir de noche el tiempo de palabra de algunos partidos, infrarrepresentados durante el día. Muchos países tienen un regulador audiovisual: busca lo que publica."),
   A3("Which parties does my favourite outlet invite most at peak times?","Quels partis mon média préféré invite-t-il le plus aux heures de grande écoute ?","¿Qué partidos invita más mi medio favorito en horario de máxima audiencia?"),
   "https://conseil-etat.fr/site/publications-colloques/rapports-d-activite/bilan-d-activite-2023/le-pluralisme-de-l-information-un-imperatif-democratique"]
 ],
 vf_h:A3("True or false?","Vrai ou faux ?","¿Verdadero o falso?"),
 vf_p:A3("Six statements heard everywhere. Your turn.","Six phrases qu’on entend partout. À vous de jouer.","Seis frases que se oyen por todas partes. Te toca."),
 vf_t:A3("True","Vrai","Verdadero"),vf_f:A3("False","Faux","Falso"),
 vf_ok:A3("Right.","Bonne réponse.","Correcto."),vf_ko:A3("Not quite.","Pas tout à fait.","No del todo."),
 vf_score:A3("correct answers","bonnes réponses","respuestas correctas"),
 vf:[
  [false,A3("A public broadcaster is necessarily the government’s mouthpiece.","Un média public est forcément la voix du gouvernement.","Un medio público es necesariamente la voz del gobierno."),A3("False in a democracy: the law protects its independence (strengthened in the EU since 2025). True in an authoritarian regime.","Faux dans une démocratie : la loi protège son indépendance (renforcée dans l’UE depuis 2025). Vrai dans un régime autoritaire.","Falso en una democracia: la ley protege su independencia (reforzada en la UE desde 2025). Verdadero en un régimen autoritario.")],
  [true,A3("An influencer must say when they are paid for a promotion.","Un influenceur doit signaler quand il est payé pour une promotion.","Un influencer debe indicar cuándo le pagan por una promoción."),A3("True in France since 2023: “Advertising” or “Commercial collaboration” label.","Vrai en France depuis 2023 : mention « Publicité » ou « Collaboration commerciale ».","Verdadero en Francia desde 2023: mención «Publicidad» o «Colaboración comercial».")],
  [false,A3("Having an editorial line always means manipulating.","Avoir une ligne éditoriale, c’est forcément manipuler.","Tener una línea editorial siempre es manipular."),A3("False: an opinion outlet is legitimate if it says so. The problem is a hidden line.","Faux : un média d’opinion est légitime s’il l’assume. Le problème, c’est la ligne cachée.","Falso: un medio de opinión es legítimo si lo asume. El problema es la línea oculta.")],
  [false,A3("Nobody checks politicians’ speaking time on TV.","Personne ne contrôle le temps de parole des politiques à la télé.","Nadie controla el tiempo de palabra de los políticos en la tele."),A3("False in France: channels report it every month to the regulator, which publishes a review every quarter.","Faux en France : les chaînes le déclarent chaque mois au régulateur, qui en fait un bilan chaque trimestre.","Falso en Francia: las cadenas lo declaran cada mes al regulador, que publica un balance cada trimestre.")],
  [true,A3("The angrier a video makes you, the more likely you are to see others like it.","Plus une vidéo vous met en colère, plus vous risquez d’en voir d’autres.","Cuanto más te enfada un vídeo, más probable es que veas otros parecidos."),A3("True: time spent watching is the main signal. Lingering is voting.","Vrai : le temps passé est le signal principal. S’attarder, c’est voter.","Verdadero: el tiempo de visionado es la señal principal. Detenerse es votar.")],
  [false,A3("A “citizens’” group on social media is necessarily independent of parties.","Un groupe « citoyen » sur les réseaux est forcément indépendant des partis.","Un grupo «ciudadano» en redes es necesariamente independiente de los partidos."),A3("False: check who runs it.","Faux : regardez qui l’administre.","Falso: mira quién lo administra.")]
 ]
});
