ALGO_STATE.vf={};
function algoVfItem(i){const v=ALGO.vf[i],a=ALGO_STATE.vf[i];
  const btn=(val,lab)=>`<button type="button" class="rq-opt vf-b" data-vf="${i}" data-v="${val}" aria-pressed="${a===val}"${a!==undefined?" disabled":""}>${aT(lab)}</button>`;
  const fb=a===undefined?"":`<p class="vf-fb ${a===v[0]?"ok":"ko"}"><b>${aT(a===v[0]?ALGO.vf_ok:ALGO.vf_ko)}</b> ${aT(v[2])}</p>`;
  return `<div class="vf-i" id="vf-${i}"><p class="vf-s">${aT(v[1])}</p><div class="rq-opts">${btn(true,ALGO.vf_t)}${btn(false,ALGO.vf_f)}</div><div aria-live="polite">${fb}</div></div>`}
function algoVfScore(){const k=Object.keys(ALGO_STATE.vf);if(k.length<ALGO.vf.length)return `<p class="rq-count mono">${k.length}/${ALGO.vf.length}</p>`;const ok=k.filter(i=>ALGO_STATE.vf[i]===ALGO.vf[i][0]).length;return `<p class="vf-score"><span class="mono">${ok}/${ALGO.vf.length}</span> ${aT(ALGO.vf_score)} · <button type="button" class="linkbtn vf-reset">${aT(ALGO.restart)}</button></p>`}
function algoMeca(){
  return `<section id="rmeca" class="rm-sec"><h2>${aT(ALGO.meca_h)}</h2><p class="lead">${aT(ALGO.meca_p)}</p>
   <div class="meca">${ALGO.meca.map((m,i)=>`<details class="meca-i"${i===0?" open":""}><summary><span class="mono">${String(i+1).padStart(2,"0")}</span><b>${aT(m[0])}</b></summary><div class="meca-b"><p>${aT(m[1])}</p><div class="meca-side"><p class="meca-q"><span class="eyebrow">${aT(ALGO.ask)}</span>${aT(m[2])}</p>${m[3]?`<a class="src-a" href="${m[3]}" target="_blank" rel="noopener">${esc(srcNamed(m[3]))}</a>`:""}</div></div></details>`).join("")}</div>
   <div class="vf" id="vf"><h3>${aT(ALGO.vf_h)}</h3><p class="rm-p">${aT(ALGO.vf_p)}</p><div class="vf-grid">${ALGO.vf.map((_,i)=>algoVfItem(i)).join("")}</div><div id="vf-score">${algoVfScore()}</div></div></section>`;
}
document.addEventListener("click",e=>{
  const r=e.target.closest&&e.target.closest(".vf-reset");
  if(r){ALGO_STATE.vf={};const box=document.getElementById("rmeca");if(box)box.outerHTML=algoMeca();return}
  const b=e.target.closest&&e.target.closest(".vf-b");if(!b||b.disabled)return;
  const i=+b.dataset.vf;if(ALGO_STATE.vf[i]!==undefined)return;ALGO_STATE.vf[i]=b.dataset.v==="true";
  const it=document.getElementById("vf-"+i);if(it)it.outerHTML=algoVfItem(i);
  const sc=document.getElementById("vf-score");if(sc)sc.innerHTML=algoVfScore();
});
