/* v179 (25/11/2026): « Reprendre la main » rewritten for a 14-year-old reader (idea of François): sentences of 15 words at most,
   one idea per sentence, everyday words. Same facts and sources. The study figures in the result are folded.
   ALGO_SIMPLE=false keeps the previous wording (nothing is overwritten unless the flag is on). */
const ALGO_SIMPLE=true;
function algoSimplify(){if(!ALGO_SIMPLE||ALGO.simple_done)return;ALGO.simple_done=true;
 Object.assign(ALGO,{
  lead:A3("Your feed learns from what you watch, and for how long. It is not just a game: in Romania in 2024, a presidential election was cancelled. Intelligence services had spotted a paid online campaign that was kept hidden. So, in front of every video, ask: who is speaking, and who is paying?",
   "Votre fil apprend de ce que vous regardez, et combien de temps. Ce n’est pas qu’un jeu : en Roumanie, en 2024, une élection présidentielle a été annulée. Les services de renseignement avaient repéré une campagne en ligne payée, mais cachée. Alors, devant chaque vidéo, une question : qui parle, et qui paie ?",
   "Tu feed aprende de lo que miras y de cuánto tiempo. No es solo un juego: en Rumanía, en 2024, se anuló una elección presidencial. Los servicios de inteligencia habían detectado una campaña en línea pagada y oculta. Así que, ante cada vídeo, pregúntate: ¿quién habla y quién paga?"),
  meca_p:A3("Seven simple cases. Open a card: it ends with a question to ask yourself.","Sept cas simples. Ouvrez une carte : elle finit par une question à vous poser.","Siete casos sencillos. Abre una tarjeta: termina con una pregunta para hacerte."),
  plat_p:A3("Menus change often. The names below come from each app’s help pages: yours may be slightly different.","Les menus changent souvent. Les noms ci-dessous viennent de l’aide de chaque appli : ils peuvent être un peu différents chez vous.","Los menús cambian a menudo. Los nombres de abajo vienen de la ayuda de cada app: en la tuya pueden ser un poco distintos."),
  el_p:A3("The goal is not to change your mind. It is to see how others tell the same story, and to check what matters.","Le but n’est pas de changer d’avis. C’est de voir comment d’autres racontent la même chose, et de vérifier ce qui compte.","El objetivo no es cambiar de opinión. Es ver cómo otros cuentan lo mismo, y comprobar lo importante."),
  el_steps:[A3("Write down your 5 main news sources: channels, sites, accounts you follow.","Notez vos 5 sources d’info principales : chaînes, sites, comptes que vous suivez.","Apunta tus 5 fuentes principales: cadenas, webs, cuentas que sigues."),
   A3("Add two: one from the other side (or closer to the centre), and a news agency that just gives the facts.","Ajoutez-en deux : une de l’autre bord (ou plus au centre), et une agence de presse qui donne juste les faits.","Añade dos: una del otro lado (o más de centro) y una agencia de noticias que solo dé los hechos."),
   A3("Each day, compare one story across three sources. What is a fact, what is an opinion? What is missing? What emotion are they trying to make you feel?","Chaque jour, comparez un même sujet chez trois sources. Qu’est-ce qui est un fait, qu’est-ce qui est un avis ? Qu’est-ce qui manque ? Quelle émotion veut-on vous faire ressentir ?","Cada día, compara un mismo tema en tres fuentes. ¿Qué es un hecho y qué es una opinión? ¿Qué falta? ¿Qué emoción quieren que sientas?"),
   A3("Talk for 20 minutes with someone who thinks differently. Listen without interrupting, then sum up their view until they say “yes, that’s it”.","Parlez 20 minutes avec quelqu’un qui pense autrement. Écoutez sans couper, puis résumez son avis jusqu’à ce qu’il dise « oui, c’est ça ».","Habla 20 minutos con alguien que piensa distinto. Escucha sin interrumpir y resume su opinión hasta que diga «sí, eso es».")],
  el_cases:[A3("You mostly follow one side? Add an outlet from the other side.","Vous suivez surtout un bord ? Ajoutez un média de l’autre bord.","¿Sigues sobre todo un lado? Añade un medio del otro lado."),
   A3("The other side annoys you too much? Start with one closer to the centre.","L’autre bord vous agace trop ? Commencez par un média plus au centre.","¿El otro lado te irrita demasiado? Empieza por uno más de centro."),
   A3("You mostly get news from political accounts? Add a news agency.","Vous vous informez surtout par des comptes politiques ? Ajoutez une agence de presse.","¿Te informas sobre todo por cuentas políticas? Añade una agencia de noticias.")],
  stance:A3("Our stance: vary your sources, listen to others, check. We never tell you what to think or whom to vote for.","Notre parti pris : varier ses sources, écouter les autres, vérifier. Nous ne vous disons jamais quoi penser, ni pour qui voter.","Nuestra postura: variar las fuentes, escuchar a los demás, comprobar. Nunca te decimos qué pensar ni a quién votar.")
 });
 const NUM=[A3("videos: roughly what it took TikTok to learn the tastes of test accounts. Time spent on a video counts a lot.","vidéos : c’est à peu près ce qu’il a fallu à TikTok pour connaître les goûts de faux comptes de test. Le temps passé sur une vidéo compte beaucoup.","vídeos: más o menos lo que tardó TikTok en conocer los gustos de cuentas de prueba. El tiempo que pasas en un vídeo cuenta mucho."),
  A3("of unwanted videos really go away with YouTube’s “Not interested” button. That is not much.","des vidéos qu’on ne veut pas voir disparaissent vraiment avec le bouton « Pas intéressé » de YouTube. C’est peu.","de los vídeos no deseados desaparecen de verdad con el botón «No me interesa» de YouTube. Es poco."),
  A3("influencers were paid in Romania to push a candidate, without saying it was political advertising.","influenceurs ont été payés en Roumanie pour pousser un candidat, sans dire que c’était de la pub politique.","influencers cobraron en Rumanía por promocionar a un candidato, sin decir que era publicidad política.")];
 if(Array.isArray(ALGO.nums))ALGO.nums=ALGO.nums.map((n,i)=>NUM[i]?[n[0],NUM[i],...n.slice(2)]:n);
 const M=[[A3("Public TV and radio","La télé et la radio publiques","La televisión y la radio públicas"),A3("They are paid for with everyone’s money: through a tax or a fee, depending on the country. In return, they must inform everyone, without taking sides, and give a voice to different views. You can criticise them: it is our money.","Elles sont payées avec l’argent de tous : par un impôt ou une taxe, selon les pays. En échange, elles doivent informer tout le monde, sans prendre parti, et donner la parole à des avis différents. On a le droit de les critiquer : c’est notre argent.","Se pagan con el dinero de todos: con un impuesto o una tasa, según el país. A cambio, deben informar a todo el mundo, sin tomar partido, y dar voz a opiniones diferentes. Se pueden criticar: es nuestro dinero."),A3("Does it give a voice to different views? And those who want to shut it down, what do they offer instead?","Donne-t-elle la parole à des avis différents ? Et ceux qui veulent la supprimer, que proposent-ils à la place ?","¿Da voz a opiniones diferentes? Y quienes quieren suprimirla, ¿qué proponen a cambio?")],
  [A3("When one outlet attacks another","Quand un média en attaque un autre","Cuando un medio ataca a otro"),A3("Outlets compete for the same audience and the same advertisers. So when one attacks a rival, it is not a neutral referee. Be most careful with repeated attacks that suit its owner.","Les médias se disputent le même public et la même publicité. Quand un média attaque un concurrent, il n’est donc pas un arbitre neutre. Méfiez-vous surtout des attaques répétées qui arrangent son propriétaire.","Los medios se disputan el mismo público y la misma publicidad. Por eso, cuando un medio ataca a un rival, no es un árbitro neutral. Desconfía sobre todo de los ataques repetidos que convienen a su dueño."),A3("Does the one attacking have something to gain?","Celui qui attaque a-t-il quelque chose à y gagner ?","¿El que ataca tiene algo que ganar?")],
  [A3("Independent, opinionated, partisan","Indépendant, d’opinion, partisan","Independiente, de opinión, partidista"),A3("An independent outlet: no one can force what it publishes. An opinion outlet: it says openly whether it leans left, right or elsewhere. That is normal. A partisan outlet: it works for a party, sometimes while pretending to be neutral. Having a view is not the problem. Hiding it is.","Un média indépendant : personne ne peut lui imposer ce qu’il publie. Un média d’opinion : il dit clairement s’il penche à gauche, à droite ou ailleurs. C’est normal. Un média partisan : il travaille pour un parti, parfois en faisant croire qu’il est neutre. Avoir un avis n’est pas le problème. Le cacher, si.","Un medio independiente: nadie puede imponerle lo que publica. Un medio de opinión: dice claramente si se inclina a la izquierda, a la derecha o a otro lado. Es normal. Un medio partidista: trabaja para un partido, a veces haciéndose pasar por neutral. Tener una opinión no es el problema. Esconderla, sí."),A3("Does this outlet say clearly which way it leans?","Ce média dit-il clairement de quel côté il penche ?","¿Dice claramente hacia qué lado se inclina?")],
  [A3("The owner","Le propriétaire","El dueño"),A3("A media outlet costs a lot and earns little. When someone buys several, it is often also to weigh on ideas. The warning sign: all their outlets say the same thing. In the US in 2018, dozens of local TV presenters read the same text, word for word, at their owner’s request.","Un média coûte cher et rapporte peu. Quand quelqu’un en achète plusieurs, c’est souvent aussi pour peser sur les idées. Le signal d’alerte : quand tous ses médias disent la même chose. Aux États-Unis, en 2018, des dizaines de présentateurs de chaînes locales ont lu le même texte, mot pour mot, à la demande de leur propriétaire.","Un medio cuesta mucho y gana poco. Cuando alguien compra varios, a menudo es también para influir en las ideas. La señal de alarma: que todos sus medios digan lo mismo. En Estados Unidos, en 2018, decenas de presentadores de cadenas locales leyeron el mismo texto, palabra por palabra, a petición de su dueño."),A3("Do the owner’s other outlets all say the same thing?","Les autres médias du même propriétaire disent-ils tous la même chose ?","¿Los otros medios del mismo dueño dicen todos lo mismo?")],
  [A3("How influencers make money","Comment les influenceurs gagnent de l’argent","Cómo ganan dinero los influencers"),A3("From platform ads, brand deals, shopping links, live donations and their own products. The more a video makes people react, the more it earns. In many countries, paid content must be labelled. It is not always done, as in Romania.","Avec la pub de la plateforme, les partenariats avec des marques, les liens d’achat, les dons en direct et leurs propres produits. Plus une vidéo fait réagir, plus elle rapporte. Dans beaucoup de pays, un contenu payé doit être signalé. Ce n’est pas toujours fait, comme en Roumanie.","Con la publicidad de la plataforma, colaboraciones con marcas, enlaces de compra, donaciones en directo y sus propios productos. Cuanto más reacciona la gente a un vídeo, más dinero da. En muchos países, el contenido pagado debe indicarse. No siempre se hace, como en Rumanía."),A3("If this video makes me angry, who makes money?","Si cette vidéo m’énerve, qui gagne de l’argent ?","Si este vídeo me enfada, ¿quién gana dinero?")],
  [A3("Groups and channels on social media","Groupes et chaînes sur les réseaux","Grupos y canales en las redes"),A3("A Facebook group, a Telegram channel or a WhatsApp group can look like it is run by people like you. Sometimes it is run by activists or a party. That is allowed, but it should be said.","Un groupe Facebook, une chaîne Telegram ou un groupe WhatsApp peut avoir l’air d’être fait par des gens comme vous. Parfois, il est animé par des militants ou un parti. Ce n’est pas interdit, mais ça devrait être dit.","Un grupo de Facebook, un canal de Telegram o un grupo de WhatsApp pueden parecer hechos por gente como tú. A veces los gestionan militantes o un partido. No está prohibido, pero debería decirse."),A3("Who runs this group, and do they say so?","Qui gère ce groupe, et le dit-il ?","¿Quién gestiona este grupo, y lo dice?")],
  [A3("Who gets on TV, and at what time","Qui passe à la télé, et à quelle heure","Quién sale en la tele, y a qué hora"),A3("In many countries, each party’s speaking time on TV is counted. In France, channels report it every month. The time of day matters too: 3 a.m. is not the evening news.","Dans beaucoup de pays, on compte le temps de parole de chaque parti à la télé. En France, les chaînes le déclarent chaque mois. L’heure compte aussi : passer à 3 h du matin, ce n’est pas passer au journal du soir.","En muchos países se cuenta el tiempo de palabra de cada partido en la tele. En Francia, las cadenas lo declaran cada mes. La hora también cuenta: las 3 de la mañana no son el telediario de la noche."),A3("Which parties does my favourite channel invite most at peak times?","Quels partis ma chaîne préférée invite-t-elle le plus aux heures où tout le monde regarde ?","¿Qué partidos invita más mi cadena favorita en las horas de máxima audiencia?")]];
 if(Array.isArray(ALGO.meca)&&ALGO.meca.length===M.length)ALGO.meca=ALGO.meca.map((m,i)=>[m[0],M[i][1],M[i][2],...m.slice(3)]);
 const V=ALGO.v2;
 V.why=A3("What you see every day shapes what you think, and how you vote. Here, you learn to choose what you watch.","Ce que vous voyez chaque jour change ce que vous pensez, et votre vote. Ici, vous apprenez à choisir vous-même ce que vous regardez.","Lo que ves cada día cambia lo que piensas, y tu voto. Aquí aprendes a elegir tú lo que miras.");
 V.paid[0][1]=A3("They are labelled “Sponsored”. Since October 2025, Facebook, Instagram and Google no longer accept political ads in the EU.","Elles portent la mention « Sponsorisé ». Depuis octobre 2025, Facebook, Instagram et Google n’acceptent plus de pub politique dans l’Union européenne.","Llevan la etiqueta «Patrocinado». Desde octubre de 2025, Facebook, Instagram y Google ya no aceptan publicidad política en la UE.");
 V.paid[1][1]=A3("They must say when they are paid. It is not always done: it happened in Romania.","Ils doivent dire quand ils sont payés. Ce n’est pas toujours fait : c’est arrivé en Roumanie.","Deben decir cuándo cobran. No siempre lo hacen: pasó en Rumanía.");
 V.paid[2][1]=A3("Dozens of accounts post the same thing at the same time to push a topic. A topic that pops up everywhere at once? Be careful.","Des dizaines de comptes publient la même chose en même temps pour faire monter un sujet. Un sujet qui surgit partout d’un coup ? Méfiance.","Decenas de cuentas publican lo mismo a la vez para hacer subir un tema. ¿Un tema que aparece de golpe en todas partes? Cuidado.");
}
function algoPage2(){
  if(typeof xpSwap==="function")xpSwap();
  algoSimplify();
  const V=ALGO.v2,th=cols=>`<tr>${cols.map(c=>`<th scope="col">${aT(c)}</th>`).join("")}</tr>`;
  return `<div class="chead rm-head" style="grid-template-columns:minmax(0,1fr)"><div><p class="eyebrow">${aT(ALGO.eye)}</p>${algoTitle("h1")}<p class="lead" style="margin-top:12px">${aT(V.lead)}</p>
   <ol class="rm-path">${V.steps.map(([id,h,s],i)=>`<li><a role="button" tabindex="0" data-jump="${id}"><span class="mono">${i+1}</span><b>${aT(h)}</b><small>${aT(s)}</small></a></li>`).join("")}</ol>
   <p class="rm-why"><b>${aT(V.why_h)}</b> ${aT(V.why)}</p></div></div>
  <section id="b-test" class="rm-block">${algoBlockHead("b-test")}
   <section id="rtest" class="rm-sec">${typeof ALGO_XP!=="undefined"&&ALGO_XP?algoXp().replace("<h2","<h3").replace("</h2>","</h3>"):algoQuiz("f")}</section></section>
  <section id="b-comp" class="rm-block">${algoBlockHead("b-comp")}
   <section id="rcomprendre" class="rm-sec"><h3>${aT(ALGO.comp_h)}</h3><p class="lead">${aT(ALGO.lead)}</p>${algoNums()}<details class="rm-more"><summary>${aT(V.comp_more)}</summary>${ALGO.comp_p.map(p=>`<p class="rm-p">${aT(p)}</p>`).join("")}</details></section>
   <section id="rpaid" class="rm-sec"><h3>${aT(V.paid_h)}</h3><div class="rm-paid">${V.paid.map(([h,x,u])=>`<div class="mcard"><b>${aT(h)}</b><span>${aT(x)}</span>${u?`<a class="src-a" href="${u}" target="_blank" rel="noopener">${esc(srcNamed(u))}</a>`:""}</div>`).join("")}</div>
    <div class="rm-reflex"><p class="eyebrow">${aT(V.reflex_h)}</p><ol>${V.reflex.map(r=>`<li>${aT(r)}</li>`).join("")}</ol></div></section>
   ${algoMeca().replace("<h2>","<h3>").replace("</h2>","</h3>")}
   <details class="rm-more" id="rqui"><summary>${aT(V.more_qui)}</summary><p class="lead">${aT(ALGO.qui_p)}</p>
    <div class="tablebox"><table class="rm-t"><thead>${th(ALGO.types_cols)}</thead><tbody>${ALGO.types.map(r=>`<tr><th scope="row">${aT(r[0])}</th><td>${aT(r[1])}</td><td>${aT(r[2])}</td></tr>`).join("")}</tbody></table></div>
    <p><a href="#medias">${aT(ALGO.media_go)}</a></p>
    <h3>${aT(ALGO.acc_h)}</h3><p class="rm-p">${aT(ALGO.acc_p)}</p>
    <div class="tablebox"><table class="rm-t"><thead>${th(ALGO.acc_cols)}</thead><tbody>${ALGO.acc.map(r=>`<tr><th scope="row">${aT(r[0])}</th><td>${aT(r[1])}</td><td>${aT(r[2])}</td></tr>`).join("")}</tbody></table></div>
    <p class="note">${aT(ALGO.acc_note)}</p></details></section>
  <section id="b-act" class="rm-block">${algoBlockHead("b-act")}
   <section id="rreset" class="rm-sec"><h3>${aT(ALGO.plat_h)}</h3><p class="lead">${aT(ALGO.plat_p)}</p>
    <div class="tablebox"><table class="rm-t"><thead>${th(ALGO.plat_cols)}</thead><tbody>${ALGO.plat.map(p=>`<tr id="rreset-${p[0].toLowerCase()}"><th scope="row">${p[3]?`<a href="${p[3]}" target="_blank" rel="noopener">${p[0]}</a>`:p[0]}</th><td>${aT(p[1])}</td><td>${aT(p[2])}</td></tr>`).join("")}</tbody></table></div></section>
   <details class="rm-more"><summary>${aT(V.rhythm_more)}</summary><h3>${aT(ALGO.steps_h)}</h3>${algoSteps()}
    <h3>${aT(ALGO.rhythm_h)}</h3><div class="levels">${ALGO.rhythm.map(r=>`<div class="level"><b>${aT(r[0])}</b><span>${aT(r[1])}</span></div>`).join("")}</div></details>
   <section id="relargir" class="rm-sec"><h3>${aT(ALGO.el_h)}</h3><p class="lead">${aT(ALGO.el_p)}</p>
    <ol class="steps">${ALGO.el_steps.map(s=>`<li>${aT(s)}</li>`).join("")}</ol>
    <div class="rm-cases">${ALGO.el_cases.map(c=>`<p class="fact">${aT(c)}</p>`).join("")}</div></section>
   <details class="rm-more" id="rmonde"><summary>${aT(V.more_world)}</summary><p class="lead">${aT(ALGO.world_p)}</p>
    <div class="mgrid">${ALGO.world.map(w=>`<div class="mcard"><b>${aT(w[0])}</b><span>${aT(w[1])}</span><a class="src-a" href="${w[2]}" target="_blank" rel="noopener">${esc(srcNamed(w[2]))}</a></div>`).join("")}</div></details>
   ${algoBand()}
   <p class="rm-stance">${aT(ALGO.stance)}</p></section>
  <section class="rm-sec sources"><b>${aT(ALGO.src_h)}</b><ul>${[...ALGO.srcs,...(ALGO.srcs.some(s=>s[1]===V.paid[0][2])?[]:[["Meta, “Ending Political, Electoral and Social Issue Advertising in the EU” (2025)",V.paid[0][2]]])].map(s=>`<li><a href="${s[1]}" target="_blank" rel="noopener">${esc(s[0])}</a></li>`).join("")}</ul></section>`;
}
