/* Wages (16 Nov 2026): ILO minimum wage with world rank, median earnings next to it. Neutral cells: no colour, no better/worse. */
const fmtN=n=>Math.round(n).toLocaleString(lang==="en"?"en-GB":lang==="fr"?"fr-FR":"es-ES");
const WTYPE={"Regional":L3("regional minimums","minimums régionaux","mínimos regionales"),"Occupational":L3("set by occupation","fixé par métier","fijado por oficio")};
function wageMetric(k,key){
  const W=(typeof WAGES!=="undefined")?WAGES:{mw:{},med:{}},U=L3("PPP $/month","$ PPA/mois","$ PPA/mes"),dash=s=>({main:"—",unit:"",sub:tr(s),rate:"na",ref:null});
  if(key==="mw"){const e=W.mw[k],M=W.mw._meta||{};
    if(!e)return dash(L3("no data published","aucune donnée publiée","sin datos publicados"));
    if(e.none)return dash(k==="northkorea"?L3("no data published","aucune donnée publiée","sin datos publicados"):L3("no national statutory minimum wage","pas de salaire minimum national légal","sin salario mínimo nacional legal"));
    if(!e.rank)return dash(L3("amount published in local currency only, not ranked","montant publié en monnaie locale seulement, non classé","importe publicado solo en moneda local, sin clasificar"));
    const ty=WTYPE[e.type]?" · "+tr(WTYPE[e.type]):"";
    return{main:fmtN(e.ppp),unit:tr(U),sub:`${ordinal(e.rank)} / ${M.n} · ≈ ${fmtN(e.usd)} US$ · ${M.year}${ty}`,rate:"na",ref:null,tip:"ILOSTAT · "+M.year+" · 2021 PPP $"}}
  const e=W.med[k];
  if(!e||e.none)return dash(L3("no comparable official figure","pas de chiffre officiel comparable","sin cifra oficial comparable"));
  const st=e.stat==="median"?L3("median","médian","mediana"):L3("mean, no median published","moyenne, pas de médian publié","media, sin mediana publicada");
  const tip=`${e.src||""}${e.scope?" · "+e.scope:""}`;
  if(e.ppp)return{main:fmtN(e.ppp),unit:tr(U),sub:`${tr(st)} (${e.year}) · ${fmtN(e.v)} ${e.cur}`,rate:"na",ref:null,tip};
  return{main:fmtN(e.v),unit:`${e.cur}/${tr(L3("month","mois","mes"))}`,sub:`${tr(st)} (${e.year})`,rate:"na",ref:null,tip}}
Object.assign(MTX,{
 mw:{n:L3("Minimum wage (ILO)","Salaire minimum (OIT)","Salario mínimo (OIT)"),w:L3("Statutory gross monthly minimum wage in 2024, in 2021 PPP dollars (corrected for the cost of living), and rank among the countries the ILO covers (1st = highest). US dollars at market rates below.","Salaire minimum légal brut mensuel en 2024, en dollars PPA 2021 (corrigés du coût de la vie), et rang parmi les pays couverts par l'OIT (1er = le plus élevé). En dessous, l'équivalent en dollars US au taux du marché.","Salario mínimo legal bruto mensual en 2024, en dólares PPA de 2021 (corregidos por el coste de la vida), y puesto entre los países que cubre la OIT (1.º = el más alto). Debajo, el equivalente en dólares de EE. UU. al tipo de mercado.")},
 med:{n:L3("Median wage","Salaire médian","Salario mediano"),w:L3("Gross monthly pay of the typical employee: half earn less, half earn more. Where an office publishes only the mean, the cell says so. Not ranked: sources, years and scopes differ.","Salaire brut mensuel du salarié type : la moitié gagne moins, l'autre moitié plus. Quand un institut ne publie que la moyenne, la case le dit. Pas de classement : sources, années et champs diffèrent.","Salario bruto mensual del asalariado tipo: la mitad gana menos y la otra mitad más. Cuando un instituto solo publica la media, la casilla lo indica. Sin clasificación: fuentes, años y ámbitos difieren.")}});
Object.assign(BADGE_OF,{mw:"mes",med:"mes"});
SRC.ilomw={t:"ILOSTAT, Monthly minimum wage by currency (2024)",u:"https://ilostat.ilo.org/data/"};
SRC.medw={t:"Eurostat SES 2022 + national statistics offices (median earnings)",u:"https://ec.europa.eu/eurostat/databrowser/view/earn_ses_monthly/default/table"};

const REG=(typeof BAROTICO!=="undefined")?BAROTICO:{meta:{},full:{},loading:{},planned:[],pos:{}};
function isReady(k){return !!(k&&(C[k]||REG.meta[k]||REG.full[k]))}
function info(k){if(!C[k]&&REG.full[k])ingest(k);return C[k]||REG.meta[k]}
function contOf(k){const p=REG.planned.find(x=>x[0]===k);return p?p[2]:"europe"}
function plannedSorted(){return REG.planned.slice().sort((a,b)=>tr(a[3]).localeCompare(tr(b[3]),lang))}
function readyKeys(){return plannedSorted().map(x=>x[0]).filter(isReady)}
function slugOf(k){const c=C[k]||REG.meta[k];return c&&c.name?slugify(String(typeof c.name==="string"?c.name:c.name.en).replace(/\s*\(.*?\)/g,"")):k}
function keyOfSlug(sl){return readyKeys().find(k=>slugOf(k)===sl)||(isReady(sl)?sl:null)}
function curRaw(){
  if(!PATHMODE)return (location.hash||"#accueil").slice(1);
  const parts=location.pathname.replace(/^\/(en|fr|es)(?=\/|$)/,"").split("/").filter(Boolean),h=decodeURIComponent(location.hash.slice(1))||(history.state&&history.state.sec)||"";
  if(!parts.length){if(!h)return "accueil";const [a,b]=h.split("-");const kk=keyOfSlug(a);return kk?kk+(b?"-"+h.slice(a.length+1):""):h}
  const sp=Object.keys(PAGE_SLUG).find(x=>PAGE_SLUG[x]===parts[0]);if(sp)return sp+(h?"-"+h:"");
  const k=keyOfSlug(parts[0]);if(!k)return "accueil";
  if(parts[1]==="parties")return k+"-"+(parts[2]||h||"partis");
  if(parts[1]==="government")return k+"-"+(h==="budget"?"budget":"government");
  if(SUB_RAW[parts[1]])return k+"-"+SUB_RAW[parts[1]];
  return k+(h?"-"+h:"");
}
function splitRaw(raw){const i=raw.indexOf("-");return i<0?[raw,""]:[raw.slice(0,i),raw.slice(i+1)]}
function pathFor(raw,L){L=L||lang;const [r,rest]=splitRaw(raw);
  if(r==="accueil"||!r)return `/${L}/`;
  if(PAGE_SLUG[r])return `/${L}/${PAGE_SLUG[r]}/`;
  if(isReady(r)){const b=`/${L}/${slugOf(r)}/`;if(!rest)return b;const sb=SUB_OF[rest];return sb?b+sb+"/":b+"parties/"+rest+"/"}
  return `/${L}/`}
// The in-page target (section of the home, legal paragraph, budget block) that pathFor leaves out of the URL.
function secFor(raw){const [r,rest]=splitRaw(raw);if(r==="accueil"||!r)return "";if(PAGE_SLUG[r])return rest;if(isReady(r))return rest==="budget"?"budget":"";return r}
// Page variant for titles: a tab (vote, parties, government, figures, watch, media), a party card ("party") or the system page ("").
function subOfRaw(raw){const [k,rest]=splitRaw(raw);if(!rest)return ["",""];if(SUB_OF[rest])return [SUB_OF[rest],""];const P=(typeof PARTIES!=="undefined"&&PARTIES[k])||[];return P.some(p=>p.id===rest)?["party",rest]:["",""]}
function pathLinks(root){if(!PATHMODE)return;(root||document).querySelectorAll('a[href^="#"]').forEach(a=>{const h=a.getAttribute("href");if(h.length>1){const raw=h.slice(1);if(/^legal-./.test(raw)){a.setAttribute("href",pathFor("legal")+"#"+raw.slice(6));delete a.dataset.sec;return}const sc=secFor(raw);a.setAttribute("href",pathFor(raw));if(sc)a.dataset.sec=sc}})}
function regionOf(k){const c=info(k);return (c&&c.region)||"eu"}
for(const k in REG.meta){if(!VAL[k])VAL[k]=REG.meta[k].val}
function refOf(mk,k){const R=(typeof BAROTICO_REF!=="undefined"&&BAROTICO_REF[mk])||null;const e=R&&(R[regionOf(k)]||R.world);return e?{v:e[0],l:tr(e[1]).split(" (")[0],full:tr(e[1]),u:e[2],s:e[3]}:null}
const FHS={F:L3("Free","Libre","Libre"),PF:L3("Partly free","Partiellement libre","Parcialmente libre"),NF:L3("Not free","Non libre","No libre")};
const RSFK=[[85,"good",L3("good","bonne","buena")],[70,"mid",L3("satisfactory","plutôt bonne","satisfactoria")],[55,"bad",L3("problematic","problématique","problemática")],[40,"bad",L3("difficult","difficile","difícil")],[-1,"bad",L3("very serious","très grave","muy grave")]];
const HDIC=[[0.8,"good",L3("very high","très élevé","muy alto")],[0.7,"mid",L3("high","élevé","alto")],[0.55,"bad",L3("medium","moyen","medio")],[-1,"bad",L3("low","faible","bajo")]];
const RW={good:L3("better","mieux","mejor"),mid:L3("close","proche","cerca"),bad:L3("worse","moins bien","peor")};RW.na=L3("","","");
function metric(k,key){
  if(key==="mw"||key==="med")return wageMetric(k,key);
  if(VAL[k][key]==null||(Array.isArray(VAL[k][key])&&VAL[k][key][0]==null))return{main:"—",unit:"",sub:tr(L3("no data published","aucune donnée publiée","sin datos publicados")),rate:"mid",ref:null};
  const v=VAL[k][key],o=n=>num(String(n).replace(".",",")),ref=refOf(key,k),vsr=d=>`${num(sgn(d).replace(".",","))} ${tr(L3("vs","vs","vs"))} ${ref?ref.l:""}`;
  if(key==="life"){const d=v-(ref?ref.v:81.5);return{main:o(v),unit:tr(L3("years","ans","años")),sub:vsr(d),rate:d>=1?"good":d<=-1?"bad":"mid",ref}}
  if(key==="school"){const d=v-(ref?ref.v:16.5);return{main:o(v.toFixed(1)),unit:tr(L3("years","ans","años")),sub:vsr(d),rate:d>=0.5?"good":d<=-0.5?"bad":"mid",ref}}
  if(key==="hom"){const x=Array.isArray(v)?v[0]:v,r=x/(ref?ref.v:0.88);return{main:(k==="france"?"≈":"")+o(x),unit:tr(L3("per 100,000","pour 100 000","por 100 000")),sub:`${num(r.toFixed(1).replace(".",","))} × ${ref?ref.l:""}`,rate:r<=0.8?"good":r>=1.2?"bad":"mid",ref}}
  if(key==="rsf"){const [rk,sc]=v,c=RSFK.find(x=>sc>=x[0]);return{main:`${ordinal(rk)} / 180`,unit:"",sub:`${tr(L3("score","score","puntuación"))} ${num(sc.toFixed(1).replace(".",","))} · ${tr(c[2])}`,rate:c[1],ref:null}}
  if(key==="fh"){const [sc,st]=Array.isArray(v)?v:[v,"F"];return{main:`${sc}/100`,unit:"",sub:tr(FHS[st]),rate:st==="F"?"good":st==="PF"?"mid":"bad",ref:null}}
  if(key==="cpi"){const [sc,rk]=v,d=Math.round(sc-(ref?ref.v:64));return{main:`${sc}/100`,unit:"",sub:`${ordinal(rk)} / 182 · ${d>0?"+":d<0?"−":"±"}${Math.abs(d)} ${tr(L3("vs","vs","vs"))} ${ref?ref.l:""}`,rate:d>=5?"good":d<=-5?"bad":"mid",ref}}
  if(key==="hdi"){const [rk,x]=v,c=HDIC.find(y=>x>=y[0]);return{main:ordinal(rk),unit:"",sub:`${tr(L3("HDI","IDH","IDH"))} ${num(x.toFixed(3).replace(".",","))} · ${tr(c[2])}`,rate:c[1],ref:null}}
}
/* A country file (countries/<key>.js) is turned into the same shapes as the first three countries */
function ingest(k){
  const d=REG.full[k];if(!d||C[k])return;
  let n=0;const sk=x=>{if(!x)return null;const id=`${k}_${n++}`;SRC[id]={t:x.t,u:x.u};return id};
  const gauges=["life","school","hdi","hom","rsf","fh","cpi"].map(m=>[MTX[m].n,"","",sk(d.valSrc[m]),BADGE_OF[m]]);
  gauges.push([d.sat.label,d.sat.v||"—",d.sat.u,d.sat.v?sk(d.sat.src):null,"son"]);
  C[k]=Object.assign({},d,{gauges,sources:(d.sources||[]).map(sk),gov:Object.assign({},d.gov,{satSrc:sk(d.gov.satSrc)})});
  VAL[k]=d.val;PARTIES[k]=d.parties;
  FIN[k]={};PROG[k]={};d.parties.forEach(p=>{FIN[k][p.id]=p.fin;PROG[k][p.id]=p.prog||[]});
  MEDIA.countries[k]=d.media;
}
window.__baroticoLoaded=k=>{ingest(k)};
function loadCountry(k){
  if(REG.loading[k])return;REG.loading[k]=1;
  const s=document.createElement("script");s.src=`countries/${k}.js?v=1795600000`;
  s.onload=()=>{ingest(k);render()};
  s.onerror=()=>{REG.loading[k]=0;document.getElementById("view").innerHTML=`<p class="pending" style="padding:48px 0">${t("load_err")}</p>`};
  document.head.appendChild(s);
}
function countriesMenu(compact){
  return ["europe","americas","africa","asia","oceania"].map(ct=>{const items=plannedSorted().filter(x=>x[2]===ct);if(!items.length)return "";
    const ready=items.filter(([k])=>isReady(k)),rest=items.length-ready.length;
    if(compact)return `<div class="ddcol"><p class="eyebrow">${t(ct)}</p>${ready.map(([k,,,nm])=>`<a href="#${k}">${esc(tr(nm))}</a>`).join("")}${rest?`<span class="off">+${rest} ${t("prep")}</span>`:""}</div>`;
    return `<div class="ddcol"><p class="eyebrow">${t(ct)}</p>${items.map(([k,,,nm])=>isReady(k)?`<a href="#${k}">${esc(tr(nm))}</a>`:`<span class="off">${esc(tr(nm))}</span>`).join("")}</div>`}).join("");
}
function mediaBlock(k){
  const d=MEDIA.countries[k],m=MT[lang]||MT.en;if(!d)return `<p class="pending">${t("fin_pending")}</p>`;
  const S=u=>`<a class="src-a" href="${u}" target="_blank" rel="noopener">${t("source")}</a>`,nm=x=>esc(tr(x));
  return `<p class="lead">${nm(d.ctx)} ${S(d.ctxSrc)}</p>
   <div class="block"><h3>${m.rec}</h3><div class="mgrid">${d.rec.map(([n,w,u])=>`<div class="mcard"><b>${nm(n)}</b><p>${nm(w)}</p>${S(u)}</div>`).join("")}</div></div>
   <div class="block"><h3>${m.vid}</h3><div class="mgrid">${d.vid.map(([n,w,u])=>`<div class="mcard"><b>${nm(n)}</b><p>${nm(w)}</p>${S(u)}</div>`).join("")}</div></div>
   <div class="two"><div class="block"><h3>${m.own}</h3><ul>${d.own.map(x=>`<li>${nm(x)}</li>`).join("")}</ul><p class="sources">${S(d.ownSrc)}</p></div>
   <div class="block"><h3>${m.facts}</h3><ul>${d.facts.map(([x,u])=>`<li>${nm(x)} ${S(u)}</li>`).join("")}</ul></div></div>`;
}
function aboutPage(){
  const A=t("about");
  return `<div class="chead" style="grid-template-columns:minmax(0,1fr)"><div><p class="eyebrow">${t("nav_about")}</p><h1>${A.h}</h1><p class="lead" style="margin-top:10px">${A.lead}</p></div></div>
  ${disclaimer(false)}
  <section><div class="principles">${A.items.map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join("")}</div></section>
  <section><div><p class="eyebrow">${A.how_eye}</p><h2>${A.how_h}</h2></div><ol class="steps">${A.steps.map(s=>`<li>${s}</li>`).join("")}</ol></section>`;
}
function bindFilter(){
  const bs=[...document.querySelectorAll("[data-cf]")];
  bs.forEach(b=>b.addEventListener("click",()=>{const f=b.dataset.cf;bs.forEach(x=>x.setAttribute("aria-pressed",x===b));document.querySelectorAll("tr[data-cont]").forEach(r=>r.hidden=f!=="all"&&r.dataset.cont!==f)}));
}
function closeDD(){const b=document.getElementById("dd-btn"),p=document.getElementById("dd-pays");if(b&&p){b.setAttribute("aria-expanded","false");p.hidden=true}}

