/* Section opener: title + one sentence (+ optional visual legend and (i)). */
function uxSec(key,extra){const [h,p]=t("sec")[key];return `<div class="psec-h"><h4>${esc(h)}</h4><p>${esc(p)}${extra||""}</p></div>`}
function uxLegend(){const L=t("lg");return ` <span class="lg">${["kept","mixed","consistent","gap","rights"].map(s=>`<span class="lg-c ps-${s}">${esc(L[s])}</span>`).join("")}</span> <button type="button" class="ctx-i" aria-expanded="false" aria-label="${esc(t("demo_what"))}">i</button></p><p class="ctx-p" hidden>${esc(t("lg_i"))}`}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest(".ctx-i");if(!b)return;const p=b.parentElement.nextElementSibling;if(!p||!p.classList.contains("ctx-p"))return;const o=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",o?"false":"true");p.hidden=o});
/* Two parties to compare with: the mirror on the other side and the centre (or, for a centre party, one on each side). */
function uxCompare(k,p){const L=(PARTIES[k]||[]).filter(q=>q.id!==p.id&&q.axis!=="na"&&typeof q.pos==="number");if(!L.length||typeof p.pos!=="number"||p.axis==="na")return [];
  const near=(x,ok)=>L.filter(ok).sort((a,b)=>Math.abs(a.pos-x)-Math.abs(b.pos-x))[0];const out=[];
  if(Math.abs(p.pos)<0.35){const l=near(-1,q=>q.pos<0),r=near(1,q=>q.pos>0);if(l)out.push([l,t("cmp_left")]);if(r)out.push([r,t("cmp_right")])}
  else{const m=near(-p.pos,q=>Math.sign(q.pos)===-Math.sign(p.pos));if(m)out.push([m,t("cmp_other")]);const c=near(0,q=>q!==m);if(c)out.push([c,t("cmp_centre")])}
  return out}
function uxIdea(k,p){const l=(typeof PROG!=="undefined"&&PROG[k]&&PROG[k][p.id])||[],cmp=uxCompare(k,p);
  return `<div class="idea"><p class="eyebrow">${t("idea_h")}</p><p>${esc(t("idea_p"))}</p><div class="progs">${l.map(([y,u])=>`<a class="progbtn" href="${u}" target="_blank" rel="noopener">${t("read_prog")} · ${y}</a>`).join("")}${cmp.map(([q,w])=>`<a class="progbtn cmpbtn" href="#${k}-${q.id}" data-cmp="${q.id}">${esc(t("cmp_with")(q.name))} <small>(${esc(w)})</small></a>`).join("")}</div></div>`}
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest(".cmpbtn");if(!a)return;const c=document.getElementById("party-"+a.dataset.cmp);if(!c)return;e.preventDefault();if(typeof openCard==="function")openCard(c,true);c.scrollIntoView({block:"start",behavior:"smooth"})});
function uxVerdict(k,p){const {v}=verdictOf(k,p),ed=isEdge(p);
  return `<div class="verdict${ed?" edge":""}"><p class="eyebrow">${t("verdict_k")}${ed?` · <span class="edge-tag">${p.pos<0?t("fl"):t("fr_")}</span>`:""}</p>${v?`<blockquote class="chute">${tr(v).split(/\n\n+/).map(x=>`<p>${esc(x)}</p>`).join("")}</blockquote>`:""}</div>`}
function partyCardUX(k,c,p){
  return `<article class="pcard ux" id="party-${p.id}">
   <header class="phead"><div class="ph-top"><h3>${esc(p.name)}</h3><button class="share" type="button" data-share="${k}-${p.id}">${t("copy")}</button></div>
    ${p.full&&p.full!==p.name?`<p class="pfull">${esc(p.full)}</p>`:""}
    ${demChip(p)}<dl class="pfacts"><div><dt>${t("f_lead")}</dt><dd>${esc(p.leader)}</dd></div><div><dt>${t("f_seats")}</dt><dd>${esc(tr(p.seats))}</dd></div>${bornLine(p)}</dl></header>
   <button class="ptoggle" type="button" aria-expanded="false">${t("p_open")}</button>
   ${p.axis==="na"?`<div class="plean na"><p class="leanlbl">${t("axis_na")}${p.axisNote?`<small>${esc(tr(p.axisNote))}</small>`:""}</p></div>`:`<div class="plean">${figure(p.pos,p.style)}<p class="leanlbl${isEdge(p)?" edge":""}">${esc(leanLabel(p))}${isEdge(p)?`<small>${t("edge_note")}</small>`:""}</p></div>`}
   <section class="psec">${uxSec("acts",uxLegend())}
    ${pairsBlock(k,p)}
    <div class="pblock"><b>${t("credit_all")}</b><ul>${p.ok.map(x=>`<li>${esc(tr(x))}</li>`).join("")}</ul></div>
   </section>
   <section class="psec">${uxSec("demo")}
    ${demWarn(p)}
    ${demoBlock(k,p)}
    <div class="pblock"><b>${t("funds")}</b>${finBlock(k,p)}</div>
   </section>
   <section class="psec">${uxSec("sum")}
    ${uxVerdict(k,p)}
    ${uxIdea(k,p)}
   </section>
   <button class="ptoggle pend" type="button">${t("p_close")}</button>
  </article>`;
}
/* Country page: one sentence at the top of each tab, and plain titles (the pun becomes a kicker). */
function uxCountry(k,h){if(!ux(k))return h;
  const C2=t("tabctx");h=h.replace(/(<div class="panel" id="(p-[a-z]+)"[^>]*>)/g,(m,a,id)=>C2[id]?`${a}<p class="tabctx">${esc(C2[id])}</p>`:a);
  const P=t("plain");["who_gov","citizens"].forEach(key=>{const pun=t(key),pl=P[key];if(pun&&pl&&pun!==pl)h=h.split(`<h3>${pun}</h3>`).join(`<p class="kicker">${esc(pun)}</p><h3>${esc(pl)}</h3>`)});
  [[", its promises one by one and its democracy barometer.",", its democracy barometer, who funds it, and a short summary."],[", ses promesses une par une et son baromètre démocratique.",", son baromètre démocratique, qui le finance, et un court résumé."],[", sus promesas una a una y su barómetro democrático.",", su barómetro democrático, quién lo financia y un breve resumen."]].forEach(([x,y])=>{h=h.split(x).join(y)});
  return h}
function isEdge(p){if(p.axis==="na")return false;return p.edge!=null?!!p.edge:(typeof p.pos==="number"&&p.style!=="rake"&&Math.abs(p.pos)>=1.5)}
const PSCLS={kept:"s-ok",token:"s-drop",partial:"s-run",broken:"s-rev",untested:"s-none"};
function verdictOf(k,p){const x=(typeof VERDICTS!=="undefined"&&VERDICTS[k]&&VERDICTS[k][p.id])||{};return{v:p.verdict||x.v,prom:p.prom||x.prom}}
function verdictBlock(k,p){
  const {v,prom}=verdictOf(k,p);if(!v&&!prom)return "";
  let meter="";
  if(prom&&prom.length){
    const n={kept:0,token:0,partial:0,broken:0,untested:0};prom.forEach(x=>n[x[1]]=(n[x[1]]||0)+1);
    const tested=n.kept+n.token+n.partial+n.broken,score=tested?(n.kept+n.partial*0.5+n.token*0.25)/tested:null;
    const [bh,bp]=score===null?t("untested_all"):t("bands")[score<0.25?0:score<0.5?1:score<0.75?2:3];
    const seg=["kept","token","partial","broken","untested"].filter(s=>n[s]).map(s=>`<i class="ps-${s}" style="flex:${n[s]}"></i>`).join("");
    meter=`<div class="pmeter"><div class="pm-head"><b>${t("prom_h")}</b><span class="pm-band">${bh}</span></div>
      <div class="pm-bar" role="img" aria-label="${T[lang].prom_count(n.kept,n.token,n.partial,n.broken,n.untested)}">${seg}</div>
      <p class="pm-count mono">${T[lang].prom_count(n.kept,n.token,n.partial,n.broken,n.untested).split(" · ").map(x=>`<span>${x}</span>`).join("")}</p><p class="explain">${bp}</p>
      <details><summary>${t("prom_detail")}</summary><ul class="casier promlist">${prom.map(([x,s,u,e])=>`<li><span class="stamp ${PSCLS[s]}">${s==="kept"&&!e?t("kept0"):t("pst")[s]}</span> <span class="ptxt">${esc(tr(x))}${u?` <a href="${u}" target="_blank" rel="noopener" class="src-a">${t("source")}</a>`:""}${s==="kept"&&e?` · <a href="${e}" target="_blank" rel="noopener" class="src-a">${t("effect")}</a>`:""}</span></li>`).join("")}</ul><p class="sources">${t("prom_note")}</p></details></div>`;
  }
  const ed=isEdge(p);
  return `<div class="verdict${ed?" edge":""}"><p class="eyebrow">${t("verdict_h")}${ed?` · <span class="edge-tag">${p.pos<0?t("fl"):t("fr_")}</span>`:""}</p>${meter}${v?`<blockquote class="chute">${tr(v).split(/\n\n+/).map(x=>`<p>${esc(x)}</p>`).join("")}</blockquote>`:""}</div>`;
}

