function rateWord(mk,m,long){if(!m||m.rate==="na"||m.main==="—")return "";const d=RDIR[mk],r=m.rate;const k=d?(r==="mid"?"close":(r==="good")===(d>0)?"above":"below"):(r==="good"?"hi":r==="bad"?"lo":"md");return tr((long?RLX:RWX)[k])}
