const CIND={h:L3("Indicators shown","Indicateurs affichés","Indicadores mostrados")};
function cmpLegend(){return `<div class="rlegend">${[["good",L3("More favourable on this indicator","Plus favorable sur cet indicateur","Más favorable en este indicador")],["mid",L3("Close to the reference, or middle of the scale","Proche de la référence, ou milieu de l'échelle","Cerca de la referencia, o mitad de la escala")],["bad",L3("Less favourable on this indicator","Moins favorable sur cet indicateur","Menos favorable en este indicador")]].map(([r,l])=>`<span class="rdot r-${r}">${tr(l)}</span>`).join("")}</div><p class="rnote">${tr(L3("These labels compare a country with the reference shown for that indicator. They do not rate a country overall. Whether a higher value is favourable depends on the indicator: a higher life expectancy is, a higher homicide rate is not.","Ces repères comparent un pays à la référence indiquée pour chaque indicateur. Ils ne notent pas un pays dans son ensemble. Qu'une valeur plus élevée soit favorable dépend de l'indicateur : une espérance de vie plus haute l'est, un taux d'homicides plus haut ne l'est pas.","Estas etiquetas comparan un país con la referencia indicada para cada indicador. No califican al país en su conjunto. Que un valor más alto sea favorable depende del indicador: una esperanza de vida más alta lo es; una tasa de homicidios más alta, no."))}</p>`}
