function cmpTable(defCont){
  const all=readyKeys(),conts=["europe","americas","africa","asia","oceania"];
  const mkeys=["life","school","hom","rsf","fh","cpi","mw","med"];
  const legend=cmpLegend();
  const usedConts=conts.filter(ct=>all.some(k=>contOf(k)===ct));
  const filt=usedConts.length>1?`<div class="cfilter" role="group" aria-label="${t("nav_countries")}">${[...usedConts,"all"].map(ct=>`<button type="button" class="chip" data-cf="${ct}" aria-pressed="${ct===defCont}">${ct==="all"?t("all_c"):t(ct)} <small>${ct==="all"?all.length:all.filter(k=>contOf(k)===ct).length}</small></button>`).join("")}</div>`:"";
  const ind=`<div class="cfilter cind" role="group" aria-label="${esc(tr(CIND.h))}"><span class="cind-l">${esc(tr(CIND.h))}</span>${mkeys.map(mk=>`<button type="button" class="chip" data-ci="${mk}" aria-pressed="true">${esc(tr(MTX[mk].n))}</button>`).join("")}</div>`;
  const head=`<tr><th scope="col">${t("country")}</th>${mkeys.map(mk=>`<th scope="col" data-mk="${mk}" title="${esc(tr(MTX[mk].w))}"><b>${esc(tr(MTX[mk].n))}</b> ${badge(BADGE_OF[mk])}</th>`).join("")}<th scope="col">${t("next_nat")}</th></tr>`;
  const rows=all.map(k=>{const c=info(k);return `<tr data-cont="${contOf(k)}"${defCont!=="all"&&contOf(k)!==defCont?" hidden":""}><th scope="row"><a href="#${k}">${esc(tr(c.name))}</a></th>${mkeys.map(mk=>{const m=metric(k,mk);return `<td data-mk="${mk}" class="mc r-${m.rate}"${m.tip?` title="${esc(m.tip)}"`:m.ref?` title="${esc(t("ref_l")+": "+m.ref.full+" · "+m.ref.s)}"`:""}><span class="mv">${m.main}${m.unit?` <small>${m.unit}</small>`:""}</span><span class="ms">${m.sub}</span><span class="rw">${rateWord(mk,m,0)}</span></td>`}).join("")}<td class="num">${esc(tr(c.elec.short))}</td></tr>`}).join("");
  const table=`${legend}${filt}${filt?`<p class="rnote">${tr(CONT_NOTE)} <a href="https://unstats.un.org/unsd/methodology/m49/" target="_blank" rel="noopener">${esc(t("src_link"))} : UN M49</a></p>`.replace(" : UN",lang==="fr"?" : UN":": UN"):""}${ind}<div class="tablewrap"><p class="scroll-hint" aria-hidden="true">${t("cmp_scroll")} <span class="sh-ico">→</span></p><div class="tablebox" tabindex="0" role="region" aria-label="${esc(t("cmp_h"))}"><table class="cmp cmp2"><thead>${head}</thead><tbody>${rows}</tbody></table></div><button type="button" class="scroll-more" aria-label="${esc(t("cmp_scroll"))}" onclick="(function(b){const s=b.parentNode.querySelector('.tablebox');s.scrollBy({left:s.clientWidth*0.7,behavior:'smooth'})})(this)">→</button></div>`;
  return table;
}
