function pilLS(){try{return JSON.parse(localStorage.getItem("baro_carnet")||"{}")}catch(e){return {}}}
function pilStamp(k,g){try{const L=pilLS();L[k]=L[k]||{};if(L[k][g])return;L[k][g]=1;localStorage.setItem("baro_carnet",JSON.stringify(L))}catch(e){}pilLog()}
function pilHas(k,g){const L=pilLS();if(g==="b"){try{if(localStorage.getItem("baro_xp"))return true}catch(e){}}return !!(L[k]&&L[k][g])}
function pilLogView(k){const n=["c","v","b"].filter(g=>pilHas(k,g)).length;
 return `<div class="carnet" id="carnet" data-k="${k}"><p class="carnet-h">${aT(PILT.log_h)} · ${esc(tr(C[k].name))} <span class="mono">${n}/3</span></p><ul class="carnet-s">${["c","v","b"].map(g=>{const on=pilHas(k,g);return `<li class="pil-${g}${on?" on":""}" title="${on?aT(PILT.log_done):aT(PILT.log_todo)+" "+aT(PILT.log_how[g])}"><span class="stamp-i">${PILI[g]}</span><span><b>${aT(PILT.log[g])}</b><small>${on?aT(PILT.log_done):aT(PILT.log_todo)+" "+aT(PILT.log_how[g])}</small></span></li>`}).join("")}</ul><details class="carnet-n"><summary>?</summary>${aT(PILT.log_note)}</details></div>`}
function pilLog(){const e=document.getElementById("carnet");if(e)e.outerHTML=pilLogView(e.dataset.k)}
