/* Barotico: "Where public money goes" card (government tab). Data: budget.js (BUDGET[k]). Pure SVG, no library. */
const BKEYS=["soc","hea","edu","eco","int","def","sec","oth"];
const BCRISES=[[2008.7,"crisis_fin"],[2020.2,"crisis_covid"],[2022.15,"crisis_energy"]];
function bYear(d){const [y,m,dd]=d.split("-").map(Number);return y+((m-1)*30.4+dd)/365}
function budgetBlock(k,mini){
  const B=(typeof BUDGET!=="undefined"&&BUDGET[k])||null;if(!B)return "";
  const X0=B.y0,X1=Math.max(B.y1,B.m0+B.debt.length-1)+1;
  const W=mini||window.innerWidth<640?400:720,L=34,R=10,iw=W-L-R,x=y=>L+(y-X0)/(X1-X0)*iw;
  const ori=o=>t("b_ori")[o]||"";
  const fmt=v=>v==null?"–":num(String(v).replace(".",","));
  // government bands behind a chart of height h (top offset t0)
  const bands=(t0,h,labels)=>B.pres.map(([a,b,n,o,sh],i)=>{const xa=Math.max(L,x(bYear(a))),xb=Math.min(L+iw,x(bYear(b)));if(xb<=xa)return "";
    const raw=sh||n.split(" ").slice(1).join(" ")||n,nm=esc(raw),wd=xb-xa;return `<rect x="${xa.toFixed(1)}" y="${t0}" width="${wd.toFixed(1)}" height="${h}" class="bband b${i%2}"/>`+(labels&&raw.length*6.6+8<wd?`<text x="${(xa+4).toFixed(1)}" y="${t0+12}" class="blab">${nm}</text>`+(ori(o).length*6+8<wd?`<text x="${(xa+4).toFixed(1)}" y="${t0+25}" class="blab o">${ori(o)}</text>`:""):"")}).join("");
  const crises=(t0,h,labels)=>BCRISES.filter(([y])=>y>=X0&&y<=X1).map(([y,key])=>`<line x1="${x(y).toFixed(1)}" x2="${x(y).toFixed(1)}" y1="${t0}" y2="${t0+h}" class="bcri"/>`+(labels?`<text x="${(x(y)+3).toFixed(1)}" y="${t0-6}" class="bcril">${t(key)}</text>`:"")).join("");
  const xticks=(y0,h)=>{let s="";for(let y=X0;y<X1;y+=(W<500?10:5))s+=`<text x="${x(y+.5).toFixed(1)}" y="${y0+h+14}" class="btick" text-anchor="middle">${y}</text>`;return s};
  // 1. stacked areas, % of GDP
  const H1=220,T1=26,n=B.tot.length,ymax=Math.ceil((Math.max(...B.tot)+8)/10)*10,yy=v=>T1+H1-(v/ymax)*H1;
  let base=new Array(n).fill(0),areas="";
  BKEYS.forEach((key,ci)=>{const top=base.map((b,i)=>b+(B.cat[key][i]||0));
    const pts=top.map((v,i)=>`${x(X0+i+.5).toFixed(1)},${yy(v).toFixed(1)}`).concat(base.map((v,i)=>`${x(X0+i+.5).toFixed(1)},${yy(v).toFixed(1)}`).reverse()).join(" ");
    areas+=`<polygon points="${pts}" class="bs${ci+1}"/>`;base=top});
  let grid="";for(let v=0;v<=ymax;v+=10)grid+=`<line x1="${L}" x2="${L+iw}" y1="${yy(v).toFixed(1)}" y2="${yy(v).toFixed(1)}" class="bgrid"/><text x="${L-6}" y="${(yy(v)+4).toFixed(1)}" class="btick" text-anchor="end">${v}</text>`;
  const svg1=`<svg class="bchart" data-k="${k}" data-c="stack" viewBox="0 0 ${W} ${T1+H1+22}" role="img" aria-label="${esc(t("b_h1"))}">${bands(T1,H1,true)}${grid}${areas}${crises(T1,H1,true)}${xticks(T1,H1)}<line class="bhov" x1="0" x2="0" y1="${T1}" y2="${T1+H1}" style="display:none"/></svg>`;
  const legend=`<ul class="blegend">${BKEYS.map((key,ci)=>`<li><i class="bs${ci+1}"></i>${t("b_cat")[key]} <span class="mono">${fmt(B.cat[key][n-1])}</span></li>`).join("")}</ul>`;
  // 2. small multiples, own scale each
  const sm=BKEYS.map((key,ci)=>{const s=B.cat[key],mn=Math.min(...s),mx=Math.max(...s),pad=(mx-mn)*.15||.2,w2=220,h2=54,l2=4,r2=4,
    sx=i=>l2+i/(n-1)*(w2-l2-r2),sy=v=>4+(h2-8)-(v-(mn-pad))/((mx+pad)-(mn-pad))*(h2-8);
    const d=s.map((v,i)=>`${i?"L":"M"}${sx(i).toFixed(1)},${sy(v).toFixed(1)}`).join("");
    const pb=B.pres.map(([a,b],i)=>{const xa=Math.max(l2,sx(bYear(a)-X0-.5)),xb=Math.min(w2-r2,sx(bYear(b)-X0-.5));return xb>xa?`<rect x="${xa.toFixed(1)}" y="0" width="${(xb-xa).toFixed(1)}" height="${h2}" class="bband b${i%2}"/>`:""}).join("");
    const ch=s[n-1]-s[0];
    return `<div class="bsm"><p><i class="bs${ci+1}"></i><b>${t("b_cat")[key]}</b></p><svg viewBox="0 0 ${w2} ${h2}" class="bspark">${pb}<path d="${d}" class="bline"/><circle cx="${sx(n-1).toFixed(1)}" cy="${sy(s[n-1]).toFixed(1)}" r="3" class="bdot"/></svg><p class="mono bsmv">${fmt(s[0].toFixed(1))} → ${fmt(s[n-1].toFixed(1))} <span>(${ch>=0?"+":"−"}${fmt(Math.abs(ch).toFixed(1))})</span></p></div>`}).join("");
  // 3. macro: debt (line), deficit and growth (bars), one axis each
  const macro=(key,arr,kind,s0)=>{s0=s0==null?B.m0:s0;const m=arr.length,H=80,T=8,vals=arr.filter(v=>v!=null),mn=Math.min(0,...vals),mx=Math.max(0,...vals),yv=v=>T+H-(v-mn)/(mx-mn||1)*H;
    let g=`<line x1="${L}" x2="${L+iw}" y1="${yv(0).toFixed(1)}" y2="${yv(0).toFixed(1)}" class="bzero"/>`,marks="";
    const step=Math.max(Math.abs(mn),Math.abs(mx))>60?50:5;for(let v=Math.ceil(mn/step)*step;v<=mx;v+=step)if(v)g+=`<line x1="${L}" x2="${L+iw}" y1="${yv(v).toFixed(1)}" y2="${yv(v).toFixed(1)}" class="bgrid"/><text x="${L-6}" y="${(yv(v)+4).toFixed(1)}" class="btick" text-anchor="end">${v}</text>`;
    if(kind==="line"){marks=`<path d="${arr.map((v,i)=>`${i?"L":"M"}${x(s0+i+.5).toFixed(1)},${yv(v).toFixed(1)}`).join("")}" class="bline bdebt"/>`}
    else{const bw=iw/(X1-X0)*.6;marks=arr.map((v,i)=>v==null?"":`<rect x="${(x(s0+i+.5)-bw/2).toFixed(1)}" y="${Math.min(yv(v),yv(0)).toFixed(1)}" width="${bw.toFixed(1)}" height="${Math.max(1,Math.abs(yv(v)-yv(0))).toFixed(1)}" rx="2" class="bbar ${v<0?"neg":"pos"}"/>`).join("")}
    const last=arr[m-1];
    return `<div class="bmac"><p class="bmh"><b>${t("b_mac")[key]}</b> <span class="mono">${s0+m-1} : ${fmt(last)} %</span></p><svg class="bchart" data-k="${k}" data-c="${key}" viewBox="0 0 ${W} ${T+H+22}">${bands(T,H,false)}${g}${marks}${crises(T,H,false)}${xticks(T,H)}<line class="bhov" x1="0" x2="0" y1="${T}" y2="${T+H}" style="display:none"/></svg></div>`};
  if(mini)return `<div class="block budget mini"><h3>${t("b_mini_h")}</h3><p class="bmob">${t("b_mob")}</p><div class="bminig">${macro("tot",B.tot,"line",B.y0)}${macro("debt",B.debt,"line")}${macro("defc",B.defc,"bar")}${macro("gdp",B.gdp,"bar")}</div><p class="sources">${t("b_src")} <a href="#${k}-budget">${t("b_more")} →</a></p><div class="btip" hidden></div></div>`;
  const pmList=B.pm.map(([d,nme,o])=>`${d.slice(0,4)} ${esc(nme)} (${ori(o)})`).join(" · ");
  const table=`<details class="btable"><summary>${t("b_table")}</summary><div class="tablewrap"><table><thead><tr><th>${t("b_year")}</th>${BKEYS.map(key=>`<th>${t("b_cat")[key]}</th>`).join("")}<th>${t("b_total")}</th><th>${t("b_mac").debt}</th><th>${t("b_mac").defc}</th><th>${t("b_mac").gdp}</th></tr></thead><tbody>${Array.from({length:X1-X0},(_,i)=>{const y=X0+i,mi=y-B.m0;return `<tr><td>${y}</td>${BKEYS.map(key=>`<td>${fmt(B.cat[key][i])}</td>`).join("")}<td>${fmt(B.tot[i])}</td><td>${fmt(B.debt[mi])}</td><td>${fmt(B.defc[mi])}</td><td>${fmt(B.gdp[mi])}</td></tr>`}).join("")}</tbody></table></div></details>`;
  return `<div class="block budget"><h3>${t("b_h")}<button type="button" class="dinfo-b" aria-expanded="false" aria-label="${t("demo_what")}">i</button></h3><p class="dinfo-p" hidden>${t("b_info")}</p>
   <p class="explain">${t("b_lead")}</p><p class="bmob">${t("b_mob")}</p>
   <p class="bsub"><b>${t("b_h1")}</b> <span class="muted">${t("b_unit")}</span></p>${svg1}${legend}
   <p class="bsub"><b>${t("b_h2")}</b> <span class="muted">${t("b_h2s")}, ${B.y0} → ${B.y1}</span></p><div class="bsmg">${sm}</div>
   <p class="bsub"><b>${t("b_h3")}</b></p>${macro("debt",B.debt,"line")}${macro("defc",B.defc,"bar")}${macro("gdp",B.gdp,"bar")}
   <p class="sources">${t("b_pres")}${B.pm.length?` ${t("b_pm")} ${pmList}.`:""}</p>
   <p class="sources">${t("b_src")} <a href="${BUDGET_SRC.cofog}" target="_blank" rel="noopener">COFOG</a> · <a href="${BUDGET_SRC.debt}" target="_blank" rel="noopener">${t("b_mac").debt}</a> · <a href="${BUDGET_SRC.gdp}" target="_blank" rel="noopener">${t("b_mac").gdp}</a></p>${table}<div class="btip" hidden></div></div>`;
}
document.addEventListener("pointermove",e=>{const s=e.target.closest&&e.target.closest("svg.bchart");const tip=s&&s.closest(".budget")?s.closest(".budget").querySelector(".btip"):null;
  document.querySelectorAll("svg.bchart .bhov").forEach(l=>l.style.display="none");if(!s||!tip){document.querySelectorAll(".budget .btip").forEach(x=>x.hidden=true);return}
  const B=BUDGET[s.dataset.k];const X0=B.y0,X1=Math.max(B.y1,B.m0+B.debt.length-1)+1,W=s.viewBox.baseVal.width,L=34,R=10,iw=W-L-R;
  const r=s.getBoundingClientRect(),vx=(e.clientX-r.left)/r.width*W;const y=Math.floor(X0+(vx-L)/iw*(X1-X0));if(y<X0||y>=X1){tip.hidden=true;return}
  const xs=L+(y+.5-X0)/(X1-X0)*iw;s.closest(".budget").querySelectorAll(`svg.bchart[data-k="${s.dataset.k}"] .bhov`).forEach(l=>{l.setAttribute("x1",xs);l.setAttribute("x2",xs);l.style.display=""});
  const f=v=>v==null?"–":num(String(v).replace(".",",")),i=y-X0,mi=y-B.m0,p=B.pres.find(([a,b])=>bYear(a)<=y+.5&&y+.5<bYear(b));
  let h=`<b>${y}</b>${p?` · ${esc(p[2])}`:""}`;
  if(s.dataset.c==="stack"){h+=`<ul>${BKEYS.map((key,ci)=>`<li><i class="bs${ci+1}"></i>${t("b_cat")[key]} <span class="mono">${f(B.cat[key][i])}</span></li>`).join("")}<li><b>${t("b_total")}</b> <span class="mono">${f(B.tot[i])}</span></li></ul>`}
  else h+=`<br>${t("b_mac")[s.dataset.c]} : <span class="mono">${f(s.dataset.c==="tot"?B.tot[i]:B[s.dataset.c][mi])} %</span>`;
  tip.innerHTML=h;tip.hidden=false;const box=tip.parentElement.getBoundingClientRect();let tx=e.clientX-box.left+14;if(tx+tip.offsetWidth>box.width)tx=e.clientX-box.left-tip.offsetWidth-14;tip.style.left=Math.max(0,tx)+"px";tip.style.top=(e.clientY-box.top+12)+"px"});

